static const float PPO_B2[4] = { -0.00133113761f, 0.00906006619f, -0.00273425458f, 0.418355197f };


static inline void ppoDenseTanh(const float *in, int n_in, int n_out,
                               const float *weights, const float *bias, float *out) {
  for (int j = 0; j < n_out; ++j) {
    float sum = bias[j];
    for (int i = 0; i < n_in; ++i) {
      sum += in[i] * weights[i * n_out + j];
    }
    out[j] = tanhf(sum);
  }
}

static inline void crazyflowPpoPolicy(const float obs[PPO_OBS_DIM], float action[4]) {
  float h0[PPO_HIDDEN_DIM];
  float h1[PPO_HIDDEN_DIM];
  float latent[4];
  ppoDenseTanh(obs, PPO_OBS_DIM, PPO_HIDDEN_DIM, &PPO_W0[0][0], PPO_B0, h0);
  ppoDenseTanh(h0, PPO_HIDDEN_DIM, PPO_HIDDEN_DIM, &PPO_W1[0][0], PPO_B1, h1);
  for (int j = 0; j < 4; ++j) {
    float sum = PPO_B2[j];
    for (int i = 0; i < PPO_HIDDEN_DIM; ++i) {
      sum += h1[i] * PPO_W2[i][j];
    }
    latent[j] = sum;
  }
  action[0] = tanhf(latent[0]) * PPO_MAX_DEPLOY_TILT_RAD;
  action[1] = tanhf(latent[1]) * PPO_MAX_DEPLOY_TILT_RAD;
  action[2] = 0.0f;
  action[3] = fminf(fmaxf(0.32f + 0.16f * tanhf(latent[3]), 0.05127031f), 0.48f);
}

